/**
 * @file optimizer_calls.c
 * @brief Select and apply inlining, specialization, and self-tail-call
 * rewrites.
 */

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Inline straight-line leaf functions and specialize calls with
// constant arguments.
#include "optimizer_calls.h"
#include "ir_free_helpers.h"
#include "ir_helpers.h"
#include "optimizer_constant_propagation.h"

#include <stdio.h>   // size_t, sprintf
#include <string.h>  // memcpy, memcmp, memmove, strcmp

enum { MAX_PARAMETERS = 8, MAX_VARIANTS = 16 };

typedef struct {
  IrFunctionId original;
  IrFunctionId clone;
  unsigned bound;
} CallVariant;

/**
 * @brief Translate a source slot ID into its cloned parameter or local slot ID.
 */
static IrStackSlotId remap_slot(IrStackSlotId slot,
                                size_t offset,
                                const IrStackSlotId* parameters,
                                size_t parameter_count) {
  return slot < parameter_count ? parameters[slot] : offset + slot;
}

/**
 * @brief Offset an SSA reference while leaving literal operands intact.
 */
static void remap_value(IrOperand* operand, size_t offset) {
  if (operand->type == IR_OP_VALUE) {
    operand->value.id += offset;
  }
}

/**
 * @brief Copy an instruction into a destination block with remapped slots and
 * values.
 *
 * @param ctx Compiler context owning the IR.
 * @param destination Function receiving the clone.
 * @param bid Destination block within that function.
 * @param old Instruction to copy; the source retains ownership of its operands.
 * @param value_offset Offset added to definitions and value references.
 * @param slot_offset Offset added to ordinary source slots.
 * @param parameters Optional map for source parameter slots.
 * @param parameter_count Number of source slots covered by the map.
 */
void optimizer_clone_instruction(Ctx* ctx,
                                 IrFunctionId destination,
                                 IrBlockId bid,
                                 IrInstruction old,
                                 size_t value_offset,
                                 size_t slot_offset,
                                 const IrStackSlotId* parameters,
                                 size_t parameter_count) {
  ir_add_instruction(ctx, destination, bid, old);
  IrInstructionArray* instructions =
      &ctx->ir.functions.data[destination].blocks.data[bid].instructions;
  IrInstruction* inst = &instructions->data[instructions->count - 1];
  inst->result =
      old.result == IR_INVALID_ID ? IR_INVALID_ID : old.result + value_offset;

  switch (ir_get_instruction_class(inst)) {
    case IR_INST_CLASS_UNARY:
      remap_value(&inst->operands.unary.operand, value_offset);
      break;
    case IR_INST_CLASS_BINARY:
      remap_value(&inst->operands.binary.left, value_offset);
      remap_value(&inst->operands.binary.right, value_offset);
      break;
    case IR_INST_CLASS_LOAD:
      inst->operands.load.source = remap_slot(
          inst->operands.load.source, slot_offset, parameters, parameter_count);
      break;
    case IR_INST_CLASS_STORE:
      inst->operands.store.target =
          remap_slot(inst->operands.store.target, slot_offset, parameters,
                     parameter_count);
      remap_value(&inst->operands.store.source, value_offset);
      break;
    case IR_INST_CLASS_CALL:
      for (size_t i = 0; i < inst->operands.call.arg_count; i++) {
        remap_value(&inst->operands.call.args[i], value_offset);
      }
      break;
  }
}

/**
 * @brief Store an already evaluated argument into its destination slot.
 */
static void emit_argument_store(Ctx* ctx,
                                IrFunctionId fid,
                                IrBlockId bid,
                                IrStackSlotId slot,
                                IrOperand value) {
  ir_add_instruction(
      ctx, fid, bid,
      (IrInstruction){.type = IR_INST_STORE,
                      .operands.store = {.source = value, .target = slot}});
}

/**
 * @brief Check the growth and control-flow restrictions for straight-line
 * inlining.
 */
static bool can_inline(const IrFunction* callee) {
  if (callee->blocks.count != 1 || callee->entrypoint != 0) {
    return false;
  }

  const IrBlock* body = &callee->blocks.data[0];
  if (body->instructions.count > 12 ||
      body->terminator.type != IR_TERMINATOR_RETURN) {
    return false;
  }

  for (size_t i = 0; i < body->instructions.count; i++) {
    const IrInstruction* inst = &body->instructions.data[i];
    if (inst->type == IR_INST_CALL && inst->operands.call.type == IR_FX_USER) {
      return false;
    }
  }

  return true;
}

/**
 * @brief Insert a straight-line callee at the call and replace its returned
 * value.
 */
// Clone a straight-line body at the call and replace uses of the returned
// value.
static void inline_call(Ctx* ctx,
                        IrFunctionId fid,
                        IrBlockId bid,
                        size_t index,
                        const IrFunction* callee) {
  IrFunction* caller = &ctx->ir.functions.data[fid];
  IrInstructionArray* instructions = &caller->blocks.data[bid].instructions;
  IrInstruction call = instructions->data[index];
  size_t previous_count = instructions->count;
  size_t slot_offset = caller->slots.count;
  size_t value_offset = caller->value_count;
  for (size_t i = 0; i < callee->slots.count; i++) {
    const IrStackSlot* slot = &callee->slots.data[i];
    ir_add_slot(ctx, fid, slot->name, slot->type);
  }

  for (size_t i = 0; i < call.operands.call.arg_count; i++) {
    emit_argument_store(ctx, fid, bid, slot_offset + i,
                        call.operands.call.args[i]);
  }

  const IrBlock* body = &callee->blocks.data[0];
  for (size_t i = 0; i < body->instructions.count; i++) {
    optimizer_clone_instruction(ctx, fid, bid, body->instructions.data[i],
                                value_offset, slot_offset, NULL, 0);
  }
  caller->value_count = value_offset + callee->value_count;

  // The leaf and its argument stores are bounded, so rotation needs no heap
  // allocation.
  IrInstruction expanded[12 + MAX_PARAMETERS];
  size_t count = instructions->count - previous_count;
  memcpy(expanded, instructions->data + previous_count,
         count * sizeof(*expanded));
  ir_free_instruction(&instructions->data[index]);
  memmove(instructions->data + index + count, instructions->data + index + 1,
          (previous_count - index - 1) * sizeof(*expanded));
  memcpy(instructions->data + index, expanded, count * sizeof(*expanded));
  instructions->count--;

  if (call.result != IR_INVALID_ID) {
    IrOperand result = body->terminator.value.return_value;
    remap_value(&result, value_offset);
    optimizer_replace_value(ctx, fid, call.result, result, false);
  }
}

/**
 * @brief Check whether a branching callee fits the CFG inlining budget.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Inline small multi-block functions and join their return paths.
static bool can_inline_cfg(const IrFunction* callee) {
  if (callee->blocks.count < 2 || callee->blocks.count > 5) {
    return false;
  }

  size_t count = 0;
  for (size_t b = 0; b < callee->blocks.count; b++) {
    const IrBlock* block = &callee->blocks.data[b];
    count += block->instructions.count;
    if (count > 16) {
      return false;
    }
    for (size_t i = 0; i < block->instructions.count; i++) {
      const IrInstruction* inst = &block->instructions.data[i];
      if (inst->type == IR_INST_CALL &&
          inst->operands.call.type == IR_FX_USER) {
        return false;
      }
    }
  }

  return true;
}

/**
 * @brief Construct an unconditional edge to the given block.
 */
static IrBlockTerminator jump_to(IrBlockId block) {
  return (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                             .value.jump_target = block};
}

/**
 * @brief Clone a branching callee and route each return to the caller's
 * continuation.
 */
// Join copied return edges at a continuation in the caller.
static void inline_cfg(Ctx* ctx,
                       IrFunctionId fid,
                       IrBlockId bid,
                       size_t index,
                       const IrFunction* callee) {
  IrFunction* caller = &ctx->ir.functions.data[fid];
  size_t slot_offset = caller->slots.count;
  size_t value_offset = caller->value_count;
  IrBlockId first = caller->blocks.count;
  for (size_t b = 0; b < callee->blocks.count; b++) {
    ir_add_block(ctx, fid);
  }

  IrBlockId continuation = ir_add_block(ctx, fid);
  IrBlock* from = &caller->blocks.data[bid];
  IrBlock* resume = &caller->blocks.data[continuation];
  IrInstruction call = from->instructions.data[index];
  size_t remaining = from->instructions.count - index - 1;
  if (remaining) {
    resume->instructions.data = TRY_MALLOC(remaining * sizeof(IrInstruction));
    memcpy(resume->instructions.data, from->instructions.data + index + 1,
           remaining * sizeof(IrInstruction));
    resume->instructions.capacity = remaining;
    resume->instructions.count = remaining;
    from->instructions.count = index + 1;
  }
  resume->terminator = from->terminator;
  from->terminator = jump_to(first + callee->entrypoint);

  for (size_t i = 0; i < callee->slots.count; i++) {
    const IrStackSlot* slot = &callee->slots.data[i];
    ir_add_slot(ctx, fid, slot->name, slot->type);
  }

  IrStackSlotId result_slot = IR_INVALID_ID;
  if (call.result != IR_INVALID_ID) {
    result_slot = ir_add_slot(ctx, fid, "$inline_return", call.result_type);
  }

  for (size_t i = 0; i < call.operands.call.arg_count; i++) {
    emit_argument_store(ctx, fid, bid, slot_offset + i,
                        call.operands.call.args[i]);
  }
  ir_free_instruction(&from->instructions.data[index]);
  array_remove(ctx, &from->instructions, index);

  for (size_t b = 0; b < callee->blocks.count; b++) {
    const IrBlock* source = &callee->blocks.data[b];
    IrBlockId target = first + b;
    for (size_t i = 0; i < source->instructions.count; i++) {
      optimizer_clone_instruction(ctx, fid, target,
                                  source->instructions.data[i], value_offset,
                                  slot_offset, NULL, 0);
    }
    IrBlockTerminator term = source->terminator;
    switch (term.type) {
      case IR_TERMINATOR_JUMP:
        term.value.jump_target += first;
        break;
      case IR_TERMINATOR_CONDITIONAL:
        term.value.conditional_target.true_target += first;
        term.value.conditional_target.false_target += first;
        remap_value(&term.value.conditional_target.condition, value_offset);
        break;
      case IR_TERMINATOR_RETURN:
        if (result_slot != IR_INVALID_ID) {
          remap_value(&term.value.return_value, value_offset);
          emit_argument_store(ctx, fid, target, result_slot,
                              term.value.return_value);
        }
        term = jump_to(continuation);
        break;
      case IR_TERMINATOR_EXIT:
        remap_value(&term.value.exit_code, value_offset);
        break;
    }
    ir_set_terminator(ctx, fid, target, term);
  }

  if (result_slot != IR_INVALID_ID) {
    size_t at = resume->instructions.count;
    ir_add_instruction(ctx, fid, continuation,
                       (IrInstruction){.type = IR_INST_LOAD,
                                       .result_type = call.result_type,
                                       .operands.load.source = result_slot});
    IrInstruction load = resume->instructions.data[at];
    memmove(resume->instructions.data + 1, resume->instructions.data,
            at * sizeof(IrInstruction));
    load.result = call.result;
    resume->instructions.data[0] = load;
  }
  caller->value_count = value_offset + callee->value_count;
}

/**
 * @brief Compare specialized argument literals when looking for a reusable
 * clone.
 */
static bool same_constant(IrOperand a, IrOperand b) {
  if (a.type != b.type) {
    return false;
  }

  switch (a.type) {
    case IR_OP_INT32:
      return a.value.int32_value == b.value.int32_value;
    case IR_OP_DOUBLE:
      return memcmp(&a.value.double_value, &b.value.double_value,
                    sizeof(a.value.double_value)) == 0;
    case IR_OP_STRING:
      return strcmp(a.value.string_value, b.value.string_value) == 0;
    case IR_OP_BOOL:
      return a.value.bool_value == b.value.bool_value;
    case IR_OP_UNIT:
      return true;
    default:
      return false;
  }
}

/**
 * @brief Clone a function whose selected parameters are initialized from
 * literals on entry.
 */
// Keep only dynamic parameters in the clone and initialize constant slots on
// entry.
static IrFunctionId specialize(Ctx* ctx,
                               IrFunctionId source,
                               const IrInstruction* call,
                               unsigned bound) {
  char name[64];
  snprintf(name, sizeof(name), "$specialized_%zu", ctx->ir.functions.count);
  IrFunctionId clone =
      ir_add_function(ctx, name, ctx->ir.functions.data[source].return_type);
  const IrFunction* original = &ctx->ir.functions.data[source];
  IrStackSlotId parameters[MAX_PARAMETERS];
  for (size_t i = 0; i < original->parameter_count; i++) {
    if (!(bound & (1u << i))) {
      parameters[i] = ir_add_parameter(ctx, clone, original->slots.data[i].name,
                                       original->slots.data[i].type);
    }
  }

  for (size_t i = 0; i < original->parameter_count; i++) {
    if (bound & (1u << i)) {
      parameters[i] = ir_add_slot(ctx, clone, original->slots.data[i].name,
                                  original->slots.data[i].type);
    }
  }

  for (size_t i = original->parameter_count; i < original->slots.count; i++) {
    ir_add_slot(ctx, clone, original->slots.data[i].name,
                original->slots.data[i].type);
  }

  ir_add_block(ctx, clone);
  for (size_t i = 0; i < original->parameter_count; i++) {
    if (bound & (1u << i)) {
      emit_argument_store(ctx, clone, 0, parameters[i],
                          call->operands.call.args[i]);
    }
  }
  ir_set_terminator(
      ctx, clone, 0,
      (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                          .value.jump_target = original->entrypoint + 1});

  for (size_t b = 0; b < original->blocks.count; b++) {
    IrBlockId bid = ir_add_block(ctx, clone);
    const IrBlock* block = &original->blocks.data[b];
    for (size_t i = 0; i < block->instructions.count; i++) {
      optimizer_clone_instruction(ctx, clone, bid, block->instructions.data[i],
                                  0, 0, parameters, original->parameter_count);
    }
    IrBlockTerminator term = block->terminator;
    if (term.type == IR_TERMINATOR_JUMP) {
      term.value.jump_target++;
    }
    if (term.type == IR_TERMINATOR_CONDITIONAL) {
      term.value.conditional_target.true_target++;
      term.value.conditional_target.false_target++;
    }
    ir_set_terminator(ctx, clone, bid, term);
  }

  ctx->ir.functions.data[clone].entrypoint = 0;
  ctx->ir.functions.data[clone].value_count = original->value_count;
  return clone;
}

/**
 * @brief Check that a function meets the specialization size and call
 * restrictions.
 */
static bool can_specialize(const IrFunction* callee) {
  if (callee->blocks.count > 12) {
    return false;
  }

  size_t total = 0;
  for (size_t b = 0; b < callee->blocks.count; b++) {
    const IrInstructionArray* instructions =
        &callee->blocks.data[b].instructions;
    total += instructions->count;
    if (total > 48) {
      return false;
    }
    for (size_t i = 0; i < instructions->count; i++) {
      const IrInstruction* inst = &instructions->data[i];
      if (inst->type == IR_INST_CALL &&
          inst->operands.call.type == IR_FX_USER) {
        return false;
      }
    }
  }

  return true;
}

/**
 * @brief Replace supported self-tail calls with argument stores and a jump to
 * entry.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Turn self calls in tail position into simultaneous parameter updates
// and a backedge.
// Turn a self-call in return position into slot updates followed by a jump.
static void eliminate_tail_calls(Ctx* ctx, IrFunctionId fid) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  if (fid == ctx->ir.entrypoint) {
    return;
  }

  for (IrBlockId bid = 0; bid < fn->blocks.count; bid++) {
    IrBlock* block = &fn->blocks.data[bid];
    IrInstructionArray* instructions = &block->instructions;
    if (block->terminator.type != IR_TERMINATOR_RETURN ||
        instructions->count == 0) {
      continue;
    }
    size_t last = instructions->count - 1;
    IrInstruction call = instructions->data[last];
    if (call.type != IR_INST_CALL || call.operands.call.type != IR_FX_USER ||
        call.operands.call.id != fid) {
      continue;
    }
    IrOperand result = block->terminator.value.return_value;
    if (fn->return_type != IR_UNIT &&
        (result.type != IR_OP_VALUE || result.value.id != call.result)) {
      continue;
    }
    for (size_t a = 0; a < call.operands.call.arg_count; a++) {
      emit_argument_store(ctx, fid, bid, a, call.operands.call.args[a]);
    }
    ir_free_instruction(&instructions->data[last]);
    array_remove(ctx, instructions, last);
    ir_set_terminator(ctx, fid, bid, jump_to(fn->entrypoint));
  }
}

/**
 * @brief Convert self-tail calls and select bounded inlining or reusable
 * specializations.
 */
void optimizer_transform_calls(Ctx* ctx) {
  DEBUG("Starting call transformation pass");

  // Share specialized bodies across sites that bind the same argument positions
  // and values.
  CallVariant variants[MAX_VARIANTS];
  size_t variant_count = 0;
  size_t function_count = ctx->ir.functions.count;
  for (IrFunctionId fid = 0; fid < function_count; fid++) {
    eliminate_tail_calls(ctx, fid);
  }

  for (IrFunctionId fid = 0; fid < function_count; fid++) {
    size_t inlined = 0;
    for (IrBlockId bid = 0; bid < ctx->ir.functions.data[fid].blocks.count;
         bid++) {
      IrInstructionArray* instructions =
          &ctx->ir.functions.data[fid].blocks.data[bid].instructions;
      for (size_t i = 0; i < instructions->count;) {
        IrInstruction* call = &instructions->data[i];
        i++;
        if (call->type != IR_INST_CALL ||
            call->operands.call.type != IR_FX_USER ||
            call->operands.call.id == fid ||
            call->operands.call.arg_count > MAX_PARAMETERS) {
          continue;
        }
        IrFunctionId original = call->operands.call.id;
        const IrFunction* callee = &ctx->ir.functions.data[original];
        if (inlined < 16 && can_inline(callee)) {
          size_t before = instructions->count;
          inline_call(ctx, fid, bid, i - 1, callee);
          i = i - 1 + instructions->count - (before - 1);
          inlined++;
          continue;
        }

        // The mask distinguishes literal arguments from values still required
        // at runtime.
        unsigned bound = 0;
        for (size_t a = 0; a < call->operands.call.arg_count; a++) {
          if (call->operands.call.args[a].type != IR_OP_VALUE) {
            bound |= 1u << a;
          }
        }
        if (!bound || !can_specialize(callee)) {
          if (inlined < 16 && can_inline_cfg(callee)) {
            inline_cfg(ctx, fid, bid, i - 1, callee);
            inlined++;
            // The suffix will be processed in its new continuation block.
            break;
          }
          continue;
        }

        // The mask alone is insufficient for reuse: compare the bound literals
        // in the clone entry stores.
        IrFunctionId clone = IR_INVALID_ID;
        for (size_t v = 0; v < variant_count; v++) {
          if (variants[v].original != original || variants[v].bound != bound) {
            continue;
          }
          const IrInstruction* stores =
              ctx->ir.functions.data[variants[v].clone]
                  .blocks.data[0]
                  .instructions.data;
          bool matches = true;
          for (size_t a = 0; a < call->operands.call.arg_count; a++) {
            if (bound & (1u << a)) {
              matches &= same_constant(call->operands.call.args[a],
                                       (stores++)->operands.store.source);
            }
          }
          if (matches) {
            clone = variants[v].clone;
            break;
          }
        }
        if (clone == IR_INVALID_ID) {
          if (variant_count == MAX_VARIANTS) {
            continue;
          }
          clone = specialize(ctx, original, call, bound);
          variants[variant_count++] = (CallVariant){original, clone, bound};
        }

        // Compact arguments in place after selecting the clone; only its
        // unbound parameters remain.
        size_t written = 0;
        for (size_t a = 0; a < call->operands.call.arg_count; a++) {
          IrOperand argument = call->operands.call.args[a];
          if (bound & (1u << a)) {
            ir_free_operand(&argument);
          } else {
            call->operands.call.args[written++] = argument;
          }
        }
        call->operands.call.arg_count = written;
        call->operands.call.id = clone;
      }
    }
  }
}
